var USE_SVG = false;

function setup() {
  createCanvas(windowWidth * 0.8, windowWidth * 0.8 / 3, USE_SVG ? SVG : P2D);
  frameRate(30);
  noFill();
  stroke("rgba(0,0,0,0.25)");
	if (USE_SVG) {
		stroke(32);
	}
  rectMode(CENTER);
  loop();
  cnt = 0;
}

function draw() {
	if (!USE_SVG) background("tan");

	let SZE = 100;
	for (let x = SZE * 0.75, dx = 1; x < width * 0.925; x += SZE * 0.01725 + dx/1.001) {
		push();
		const y = height / 2;
		const dF = noise(x / 23, y / 43, frameCount / 243) - 0.5;
		translate(x, y + SZE * dF * pow(map(x, 0, width, 1, 3), 2.5));
		const angle = noise(x / 123, y / 41, frameCount / 243) * TWO_PI;
		const szeF = noise(x / 93, y / 121, frameCount / 343);
		rotate(angle);
		if (cnt < 1000000) {
			rect(0, 0, SZE * szeF); cnt++;
		}
		pop();
		if (cnt >= 1000000) {
			// noLoop() removed for animation
			console.log(cnt, ~~(millis() / 1000), "sec");
			break;
		}
	}

	// noLoop() removed for animation
}

function keyPressed() {
	if (key === 's' || key === 'S') {
		save("epi_blowing_rects." + (USE_SVG ? "svg" : "png")); // Save the canvas as SVG
	}
}
function doubleClicked() {
  if (mouseButton !== RIGHT) setup();
}
